\label{introthm:examples}
    Let $X$ be the Cantor space. The following classes of $C^*$-algebras are singly generated:
    \begin{enumerate}
        \item crossed products $C(X) \rtimes_r G$ with a faithful trace, with $G$ a countable discrete group containing a subgroup $F$ such that the restricted action induces a simple, monotracial crossed product $C(X) \rtimes_r F$ with strict or dynamical comparison (Corollary \ref{cor:sg_crossedprod});
        \item crossed products $C(X)\rtimes_r G$ arising from profinite actions (see Remark~\ref{rmk:profinite}) on the Cantor space, and in particular the non-nuclear Bunce--Deddens algebras introduced in \cite{bell} (Examples (\ref{sg_profinite}) \& (\ref{sg_buncededdens}) below Corollary \ref{cor:sg_crossedprod});
        \item amalgamated free products over a regular copy of $C(X)$ where one factor is simple and monotracial and has strict comparison (Corollary~\ref{cor:amalgams});
        \item any tensor product of one of the above with any separable, unital $C^*$-algebra (Corollary~\ref{cor:sg_tensorprod}).
    \end{enumerate}

Let $D$ be a subalgebra of a \ensuremath{C^*}-algebra $A$. A \emph{normalizer} of $D$ in $A$ is an element $a\in A$ such that
    \begin{equation}
        aDa^*\cup a^*Da\subseteq D.
    \end{equation}
    Denote by $N_A(D)$ the set of normalizers of $D$ in $A$. Then $D$ is said to be \emph{regular} in $A$ if $\ensuremath{C^*}(N_A(D))=A$.

Let $X$ be a compact Hausdorff space and $A$ a \ensuremath{C^*}-algebra containing $C(X)$ as a \ensuremath{C^*}-subalgebra. For a normalizer $a\in N_{A}(C(X))$, write
    \begin{equation}
    \begin{aligned}
        \operatorname{supp}(a)&=\{x\in X\mid a^{*}a(x)>0\},\\
        \operatorname{ran}(a)&=\operatorname{supp}(a^{*}).
    \end{aligned}
    \end{equation}
    Then $a$ is said to be \emph{clopen} if $\operatorname{supp}(a)$ and $\operatorname{ran}(a)$ are compact open subsets of $X$. We denote by $N_{A}^{c}(C(X))$ the set of clopen normalizers of $C(X)$ in $A$.

To prove the first part of the statement, let $a\in N_{A}(C(X))$ and $\varepsilon>0$. 
    Since $X$ is 0-dimensional, we can find a clopen $K\subseteq\operatorname{supp}(a)$ such that 
    \begin{equation}
        \sup_{x\in X\setminus K} \left| a^{*}a(x)\right| \leq\varepsilon .
    \end{equation}
    Let $p=\mathbbm{1}_{K}$. Then $ap\in N_{A}^c(C(X))$ satisfies
    \begin{equation}
    \begin{aligned}
        \lVert a-ap\rVert&\leq\varepsilon\\
        \operatorname{supp}(ap)&=K\cap\operatorname{supp}(a)=K
    \end{aligned}
    \end{equation}
    since $\alpha_{ap}=\alpha_{a}|_{K}$.

    For the second part of the statement, note that since $\operatorname{supp}(a)$ is clopen, there exists $\varepsilon>0$ such that $a^*a(x)\geq \varepsilon$ for all $x\in \operatorname{supp}(a)$.
    Let $f(x)=\frac{1}{a^*a(x)}$ for $x\in \operatorname{supp}(a)$ and $f(x)=1$ otherwise. 
    Notice that $f$ is a continuous non-negative function on $X$.
    Let $v=af^{1/2}\in A$.
    Then one computes that $v^*v=fa^*a=\mathbbm{1}_{\operatorname{supp}(a)}$ and so $v$ is a partial isometry.
    One easily checks that $v$ belongs to the normalizer, provides a polar decomposition of $a$, and the required equalities hold.

\label{def:strictcomp}
    A $C^*$-algebra $B$ with non-empty tracial state space $T(B)$ is said to have \emph{strict comparison (of positive elements by bounded traces)} if for arbitrary positive elements $a,b\in (B\otimes \mathcal{K})_+$, we have 
    \begin{equation}
        d_\tau(a) < d_\tau(b) \ \forall \tau\in T(B) \implies a \precsim b,
    \end{equation}
    where
    \begin{equation}
        d_\tau(a) := \lim_{k\to\infty} \tau(a^{1/k}) \quad (\tau \in \tau(B)),
    \end{equation}
    where by abuse of notation we also write $\tau$ for the non-normalized extension of $\tau$ to $B\otimes \mathcal{K}$.

\label{def:dynamicalcomp}
    Let $B$ be a \ensuremath{C^*}-algebra with non-empty trace space and $D$ an abelian subalgebra of $B$.
    We say that $D$ has \emph{dynamical comparison} relative to $B$ if for any two projections $p,q\in D$ such that $\tau(p)<\tau(q)$ for all $\tau\in T(B)$, we have $p\precsim q$ by a partial isometry $v\in N_B(D)$.

\label{def:diffuse}
    A trace $\tau$ on a $C^*$-algebra $A$ is said to be \emph{diffuse} if the associated GNS completion $\pi_\tau(A)''$ is a diffuse von Neumann algebra, i.e.\ has no minimal projections.

    If $D$ is a $C^*$-subalgebra of $A$, we say $\tau$ is \emph{diffuse on $D$} if $\tau|_D$ is diffuse.

\label{lemma:no-atoms-in-vna}
    Let $(\ensuremath{\mathcal{M}},\tau) $ be a \ensuremath{\mathrm{II}_{1}} factor and $A\subseteq \ensuremath{\mathcal{M}} $ a regular, abelian subalgebra.
    Then $A$ is either finite dimensional or diffuse.

Let $A$ be a $\ensuremath{C^*}$-algebra. Then $gr_0(A)$ is defined as the smallest integer $n \geq 0$ such that for every $a_0, \ldots, a_n \in A_{sa}, \varepsilon> 0$ and $c\in A$, there exist $b_0, \ldots, b_n \in A_{sa}$ such that 
		\begin{equation}
			\mathrm{dist}(c, \ C^*(b_0, \ldots, b_n))< \varepsilon, \qquad \| b_i - a_i \| < \varepsilon, \quad i=0, \ldots, n.
		\end{equation}
		If no such $n$ exists, then $\mathrm{gr}_0(A) = \infty$. 
		The \emph{generator rank} of $A$ is defined as 
		\begin{equation}
			\mathrm{gr}(A):= \mathrm{gr}_0 (A^\sim),
		\end{equation}
        where $A^\sim $ is the minimal unitization of $A$.

Let $A$ be a separable $\ensuremath{C^*}$-algebra and $n \in \mathbb{N}$. Then $\mathrm{gr}(A) \leq n$ if and only if for every $a_0, \ldots, a_n \in A_{sa}$ and $\varepsilon>0$, there exist $b_0,\ldots, b_n \in A_{sa}$ such that $A = C^*(b_0, \ldots, b_n)$ and
	\begin{equation}
		\|b_i -a_i\| < \varepsilon, \qquad i=0, \ldots, n.
	\end{equation}

\label{thm:gr.ind.limits}
	Let $A$ be an inductive limit of a sequence $(A_\lambda)$ of $\ensuremath{C^*}$-algebras. Then
	\begin{equation}
		\mathrm{gr}(A) \leq  \liminf_\lambda \mathrm{gr}(A_\lambda).
	\end{equation}

\label{prop:esstracZstab}
    Let $A$ be simple, unital, tracially AF \ensuremath{C^*}-algebra. Then for any finite subset $\mathfrak{F}\subset A$, any positive contraction $a \in A$ and any $\varepsilon>0$ there is a finite dimensional \ensuremath{C^*}-algebra $F \cong \bigoplus_{k=1}^r M_{n_k}(\mathbb{C})$ and simple, infinite dimensional, unital, AF algebras $C_k$ such that $B = \bigoplus_{k=1}^r M_{n_k}(\mathbb{C}) \otimes C_k \subset A$ and, writing $p=1_B$,
    \begin{enumerate}
        \item $px \approx_\varepsilon xp$ for all $x \in \mathfrak F$,
        \item $pxp \in_\varepsilon \bigoplus M_{n_k}(\mathbb{C}) \otimes 1_{C_k}$,
        \item $1-p \precsim a$.
    \end{enumerate}

Let $\mathfrak F \subset A$ be a finite subset, $a\in A$ a positive contraction and  $\varepsilon>0$. By the TAF condition, there is a finite dimensional subalgebra $F= \bigoplus_{s=1}^r M_{_{n_s}} (\mathbb C)$ with $p=1_F$ such that
	\begin{enumerate}
		\item $xp \approx_\varepsilon px$ for all $x \in \mathfrak{F}$,
		\item $pxp \in_\varepsilon F$, and
		\item $1-p \precsim a$.
	\end{enumerate}
	As in the proof of \cite[Proposition 6.9]{FLL22}, there is a unital, simple, infinite dimensional, AF algebra $B_s$ with a unital embedding $\phi_s : B_s \to \overline{e_{11}^{(s)}Ae_{11}^{(s)}}$ such that the induced map at the level of Murray--von Neumann semigroups $V(\phi_s): V(B_s) \to V(\overline{e_{11}^{(s)}Ae_{11}^{(s)}})$ is surjective.
	Set $C_s := \phi_s(B_s) \subset \overline{e_{11}^{(s)}Ae_{11}^{(s)}}$ and $B = \bigoplus_{s=1}^r M_{n_s}(\mathbb{C}) \otimes C_s$. Observe that $B$ sits as a subalgebra of $A$ via the following map
	\begin{equation}
        \bigoplus_{s=1}^r M_{n_s}(\mathbb{C}) \otimes C_s \to A, \qquad e_{ij}^{(s)}\otimes c \mapsto e_{i1}^{(s)} \cdot c \cdot e_{1j}^{(s)}. 
	\end{equation}
	This map satisfies that $e_{ij}^{(s)} \otimes 1_{C_s} \mapsto e_{ij}^{(s)}$. Then under this identification, it follows that $pxp \in_\varepsilon \bigoplus_{s=1}^r M_{n_s}(\mathbb{C}) \otimes 1_{C_s}$. The last part of the statement is the content of \cite[Proposition 6.9]{FLL22}.

\label{lem:M_5.tracial.approx}
    Let $A$ be a simple, separable, tracially AF \ensuremath{C^*}-algebra. Let $\varepsilon, \delta > 0, a,b \in A_{sa}$ and $c \in A$. 
    Then there exists a subalgebra $\bigoplus_{s=1}^r M_{n_s}(\mathbb C) \otimes M_5(\mathbb C) \subset A$ with unit $f$ such that for all $x \in \{ a,b, c \}$
    \begin{enumerate}
        \item $fx \approx_\varepsilon xf$,

        \item $fxf \in_\varepsilon \bigoplus_{s}^r M_{n_s}(\mathbb C) \otimes 1_{M_s}$ 

        \item $\tau(1-f) < \delta$ for all $\tau \in T(A)$.

    \end{enumerate}

Set $\mathfrak F = \{a, b, c, c^*\}$. We can assume that $0 < \delta \leq \varepsilon/4$.
    Thus, by Proposition \ref{prop:esstracZstab}, there is a finite dimensional \ensuremath{C^*}-algebra $\bigoplus\limits_{s=1}^r M_{n_s}(\mathbb{C})$ and simple, infinite dimensional, unital, AF algebras $C_s$ such that $\bigoplus\limits_{s=1}^r M_{n_s}(\mathbb{C}) \otimes C_s \subset A$ and, denoting its unit by $p$, we have
    \begin{enumerate}
        \item $p x \approx_{\delta} x p$ for all $x \in \mathfrak F$,
        \item there exist $a_0, b_0, c_0 \in \bigoplus M_{n_s}(\mathbb{C}) \otimes 1_{C_s}$ such that 
        \begin{equation}
        	p a p \approx_\delta a_0, \qquad p b p \approx_\delta b_0, \qquad p c p \approx_\delta c_0, \notag 
        \end{equation}

        \item $\tau(1-p) < \delta/2$ for all $\tau \in T(A)$.
    \end{enumerate}
    Since each $C_s$ is an infinite-dimensional, simple, unital, AF algebra, there is a copy of $M_{5}(\mathbb C)$ within $C_s$ in such a way that its unit is uniformly close to $1_{C_s}$ in trace. Precisely, we will denote this copy contained in $C_s$ by $M_5^{(s)}$ and write its unit as $f_s$. Then we can assume that 
    \begin{equation} \label{eq:fs_largetrace}
    \tau(1_{C_s}- f_s) < \delta/2 \qquad \text{for all} \qquad \tau \in T(C_s). 
    \end{equation}
    Observe that for any $\tau \in T(A)$ and $1 \leq s \leq r$, simplicity yields $\tau(1_{M_s} \otimes 1_{c_s}) > 0$. It follows that 
    \begin{equation}
        \tau_s (x) = \tau(1_{M_{n_s}} \otimes 1_{C_s})^{-1} \tau(1_{M_{n_s}} \otimes x) \quad (x\in C_s)
    \end{equation}
    is a tracial state on $C_s$.
    We define
    \begin{equation}
	   f:= \bigoplus_{s=1}^r 1_{M_{n_s}} \otimes f_s. 
    \end{equation}
    Thus, for $\tau \in T(\bigoplus_s M_{n_s} \otimes C_s)$,
    \begin{equation}
        \begin{aligned}
        \tau(p-f) &= \tau\left( \bigoplus_{s=1}^r 1_{M_s} \otimes (1_{C_s} - f_s) \right) \\ 
        & = \sum_{s=1}^r \tau(1_{M_s} \otimes 1_{C_s} ) \tau_s( 1_{C_s} - f_s) \\
        & < \sum_{s=1}^r \tau(1_{M_s} \otimes 1_{C_s} ) \delta/2 = \delta/2.
        \end{aligned}
    \end{equation}
    By a similar argument, we obtain that for any $\tau \in T(A)$
    \begin{equation}
        \tau(p-f) = \tau(p) \left( \tau(p)^{-1} \tau(p-f) \right) < \delta/2. 
    \end{equation}
    This implies
    \begin{equation}
	\tau(1-f) =  \tau(1-p) + \tau(p-f) < \delta.
\end{equation}

Since $a_0, b_0, c_0 \in \bigoplus_{s=1}^r M_{n_s}( \mathbb{C}) \otimes 1_{C_s}$, these elements commute with $f$. Then, using that $f \leq p$, we have
\begin{equation}
    fa = fpa \approx_{\delta} fpap \approx_{\delta} fa_0   = a_0 f \approx_{\delta} pap f \approx_{\delta} apf = af.
\end{equation} \label{eq:fF_approxcommute}
By a similar argument, 
\begin{equation}
    f h \approx_{\varepsilon} h f
\end{equation}
for all $h \in \mathfrak F$. 
On the other hand,
\begin{equation}
    fcf = fpcpf \approx_{\varepsilon} fc_0 f = c_0 f \in \bigoplus_{s=1}^r M_{n_s}(\mathbb C) \otimes M_5^{(s)}.
\end{equation}
By the same argument, $fxf \in_\varepsilon \bigoplus_{s=1}^r M_{n_s}(\mathbb C) \otimes M_5^{(s)}$ for any $x \in \mathfrak F$.

Let us begin by assuming that $A$ is unital. 
Let $\varepsilon > 0$, $a,b \in A_{sa}$ and $c \in A$. 
According to the definition of generator rank, we will construct $x,y \in A_{sa}$ such that 
\begin{equation}\label{mainthm:eq.mu}
	a\approx_\varepsilon x, \quad b \approx_\varepsilon y, \quad \mathrm{dist}(c,C^*(x,y))< \varepsilon.
\end{equation} 

Set $\mathfrak F = \{a, b, c, c^*\}$ and $0 < \delta < \min \{\frac{\varepsilon}{15}, \frac{1}{12}\}$.
Thus, by Lemma~\ref{lem:M_5.tracial.approx}, there exists a subalgebra $\bigoplus_{s=1}^r M_{n_s}(\mathbb C) \otimes M_5^{(s)} \subset A$ with unit $f$ such that $M_5^{(s)} \cong M_5(\mathbb C)$ and
    \begin{enumerate}
        \item $fh \approx_\delta hf$ for all $h \in \mathfrak F$,

        \item there exist $a_0, b_0, c_0  \in \bigoplus_{s}^r M_{n_s}(\mathbb C) \otimes 1_{M_s}$ such that 
        $$ 
        faf \approx_\delta a_0, \qquad fbf \approx_\delta b_0, \qquad fcf \approx_\delta c_0,
        $$

        \item $\tau(1-f) < \delta$ for all $\tau \in T(A)$.

    \end{enumerate}
Let $(e_{ij}^{(s)})$ be the matrix units of $M_{5}^{(s)} $ and for $1 \leq i \leq 5$, set 
\begin{equation}
	\tilde{e}^{(s)}_{ij}:= 1_{M_{n_s}} \otimes e^{(s)}_{ij},   \qquad q_i := \bigoplus_{s=1}^r \tilde{e}^{(s)}_{ii}.
\end{equation}
It follows immediately that $(\tilde{e}_{ij}^{(s)})$ also satisfies the matrix unit relations.
We also define
\begin{equation}
    u := \bigoplus_{s=1}^r \tilde{e}_{12}^{(s)} \qquad \text{and} \qquad w:= \bigoplus_{s=1}^r \tilde{e}_{34}^{(s)}. 
\end{equation}
These are partial isometries satisfying 
\begin{equation}
	uu^* = q_1, \qquad u^*u = q_2, \qquad ww^* = q_3, \qquad w^* w = q_4.
\end{equation}

On the other hand, we have
\begin{equation}
	\tau(e) < \delta  \leq \frac{1}{6}.
\end{equation}
Then $5 \tau(e) < 1 - \tau(e)$ which yields
\begin{equation}
      \tau(e) < \frac{1-\tau(e)}{5} = \frac{\tau(f)}{5} = \tau(q_1).
\end{equation}
Then by strict comparison, there is $v \in qAe$ such that
\begin{equation}
	v^*v = e \qquad \text{and} \qquad q := vv^* \leq q_1.
\end{equation}
We define
\begin{equation}
	d := vcv^* = qv c v^* q \in qAq.
\end{equation}
Thus 
\begin{equation}
    v^* d v = v^* vcv^*v = ece.
\end{equation}

Since $eAe$ has real rank zero, we can find a self-adjoint element $a_1 \in eAe$ with finite spectrum such that $a_1 \approx_{\delta} eae$. 
After an arbitrarily small perturbation, we can assume $a_0$ and $a_1$ have disjoint spectra and are invertible.
We can write $a_0 = (a_0^{(s)}) \in \bigoplus_{s=1}^r M_{n_s}(\mathbb{C}) \otimes 1_{C_s}$. As before, after a further arbitrarily small perturbation, we can assume that the elements $a_0^{(s)}$ have pairwise disjoint spectra.
Let $0 <\mu < \delta$ be smaller than the distance between any two distinct elements in $\sigma(a_0)\cup\sigma(a_1)\cup\{0\}$.
With all this setup, we can now define our first generator:  
\begin{equation}\label{mainthm:eq.xn}
		x := a_1 + \sum_{s=1}^r \sum_{k=1}^5 \left( a_0^{(s)} + \frac{k \mu}{5} \right) \otimes e_{kk}^{(s)}.
\end{equation}
In order to somewhat simplify our notation, let us define
\begin{equation}
	z: = \bigoplus_{s=1}^r \sum_{j=1}^4 (\tilde{e}_{5j}^{(s)} + \tilde{e}_{j5}^{(s)}).
\end{equation}
We choose 
\begin{equation}
	0 < \lambda_1 , \ldots , \lambda_4 < \min\left\{\frac{\delta}{2}, \frac{\delta}{2(\|c\|+\delta)} \right\}    
\end{equation}
and define
\begin{equation}
	y:= ebe + b_0 f + \lambda_1 z +\lambda_2 \left( v + v^* \right) + \lambda_3 \left(du + u^* d^* \right) + \lambda_4 (c_0 w + w^*c_0^* ).
\end{equation}
Our choice of $\lambda_i$ guarantees that the terms in $y$ with the corresponding coefficient $\lambda_i$ have norm smaller than $\delta$.
By construction, $x$ and $y$ are self-adjoint elements. We define $B:= C^*(x,y)$.

\begin{claim}
	The generators of $B$ satisfy $x \approx_\varepsilon a$ and $y \approx_\varepsilon b$.
\end{claim}

\begin{proof}[Proof of claim]
Let us verify first that $x$ is close to $a$. Indeed,
\begin{equation} 
\begin{aligned}
	x-a & = x - eae - fae - eaf - faf \\
	& \approx_{8\delta} x-eae-faf \\
	& = x - eae - fpapf \\
	& \approx_{\delta} a_1 + \sum_{s=1}^r \sum_{k=1}^5 \left( a_0^{(s)} + \frac{k \mu}{5} \right) \otimes e_{kk}^{(s)} -eae - fa_0f \\
	& \approx_{\delta} \sum_{s=1}^r \sum_{k=1}^5 \left( a_0^{(s)} + \frac{k \mu}{5} \right) \otimes e_{kk}^{(s)} - \sum_{s=1}^r \sum_{k=1}^5 a_0^{(s)} \otimes e_{kk}^{(s)} \\
	& = \sum_{s=1}^r \sum_{k=1}^5 \frac{k \mu}{5} \otimes e_{kk}^{(s)} \\
	& \approx_{5 \delta} 0,
\end{aligned}
\end{equation}
where we used \eqref{eq:fF_approxcommute} on the second line and the definitiond of $a_0$ and $a_1$ on the fourth and  fifth lines, respectively.

On the other hand, the second generator satisfies
\begin{equation} 
\begin{aligned}
	y-b & \approx_{4 \delta} ebe + b_0 f - (ebe+fbe+ebf+fbf)  \\
	& \approx_{8\delta} ebe + b_0 f - ebe - fbf \\
	& \approx_{\delta} 0,
\end{aligned}
\end{equation} 
where we used \eqref{eq:fF_approxcommute} on the second line and the definition of $b_0$ on the third.
Our proposed generators then satisfy $a \approx_\varepsilon x$ and $b \approx_\varepsilon y$.
\end{proof}

\begin{claim}
	The elements $e, \tilde{e}_{ii}^{(s)}$ and $q_i$ belong to $B$ for $1 \leq i \leq 5$.
\end{claim}

\begin{proof}[Proof of claim]
Our choice of $\mu$ and the fact that $a_1$ and all $a_0^{(s)}$ are invertible guarantees that using a suitable continuous function we have $e$ and $\tilde{e}_{ii}^{(s)}$ are in $C^*(x) \subset B$ for $1 \leq s \leq r$ and $1 \leq i \leq 5$.
It then follows that 
\begin{equation}
    q_i = \bigoplus_{s=1}^r \tilde{e}_{ii}^{(s)}  \in C^*(x) \subset B \qquad  \text{for} \qquad 1 \leq i \leq 5. \qedhere
\end{equation}
\end{proof}

\begin{claim}\label{claim:e5i}
	The elements $\tilde{e}_{5i}^{(s)}$ and $\tilde{e}_{i5}^{(s)}$ belong to $B$ for $1 \leq i \leq 4$ and $1 \leq s \leq r$. 
\end{claim}

\begin{proof}[Proof of claim]
This claim follows from computing $\tilde{e}_{55}^{(s)} y \tilde{e}_{jj}^{(s)}$ for $1 \leq j \leq 4$. Since our expression for $y$ is rather long, we break this down into several smaller calculations.

First, since $b_0 \in \bigoplus_{s=1}^r M_{n_s}(\mathbb{C}) \otimes 1_{C_s}$, it commutes with all $\tilde{e}_{ij}^{(s)}$ and we have the following,
\begin{equation}
    \tilde{e}_{ii}^{(s)} \cdot b_0 f \cdot \tilde{e}_{jj}^{(k)}  = \delta_{ks} b_0 \cdot \tilde{e}_{ii}^{(s)} \tilde{e}_{jj}^{(s)} = \delta_{ks} \delta_{ij} b_0 \cdot \tilde{e}_{ii}^{(s)}. 
\end{equation}
Likewise, 
\begin{equation}
	\begin{aligned}
   \tilde{e}_{ii}^{(s)} \cdot z \cdot \tilde{e}_{jj}^{(k)}& = \tilde{e}_{ii}^{(s)} \left( \bigoplus_{l=1}^r \sum_{m=1}^4 (\tilde{e}_{5m}^{(l)} + \tilde{e}_{m5}^{(l)}) \right)  \tilde{e}_{jj}^{(k)} \\
    & = \sum_{m=1}^4 \left( \delta_{i5} \tilde{e}_{5m}^{(s)} \tilde{e}_{jj}^{(k)} + e_{i5}^{(s)}e_{jj}^{(k)}\right) \\
    &= \delta_{ks} \left(\delta_{i5} \tilde{e}_{5j}^{(s)} + \delta_{j5} \tilde{e}_{i5}^{(s)} \right). 
\end{aligned}
\end{equation}
Also, using that $v \in qAe$, that $\tilde{e}_{ii}^{(s)} \leq f$, and that $e$ and $\tilde{e}_{ii}^{(s)}$ are orthogonal, we get
\begin{equation}
    \tilde{e}_{ii}^{(s)} \left( v + v^* \right) \tilde{e}_{jj}^{(k)} = 0.
\end{equation}
In the same manner,  since $q \leq q_1$ and $q_1$ is orthogonal to $q_j$ for all $j \neq 1$, it follows that $q$ is orthogonal to $q_j$ for $j \neq 1$. Using that $d \in qAq$, we obtain
\begin{equation}
	\begin{aligned} 
    \tilde{e}_{ii}^{(s)} \left( du \right) \tilde{e}_{jj}^{(k)} & = \tilde{e}_{ii}^{(s)} \cdot d \left( \bigoplus_{l=1}^r  \tilde{e}_{12}^{(l)} \right) \tilde{e}_{jj}^{(k)}  \\
    & = \delta_{2j} \tilde{e}_{ii}^{(s)} \cdot d \cdot \tilde{e}_{12}^{(k)}  \\
    & = \delta_{2j} \tilde{e}_{ii}^{(s)} \cdot q_1 d \cdot \tilde{e}_{12}^{(k)}  \\
    & =  \delta_{2j} \delta_{1i} \tilde{e}_{11}^{(s)} \cdot d \cdot \tilde{e}_{12}^{(k)}. 
\end{aligned}
\end{equation}
Similarly,
\begin{equation}
    \tilde{e}_{ii}^{(s)} \left( u^*d^* \right) \tilde{e}_{jj}^{(k)} 
    = \delta_{2i} \delta_{1j} \tilde{e}_{21}^{(k)} \cdot d^* \cdot \tilde{e}_{11}^{(s)}.
\end{equation}
Proceeding as above, using that $c_0 \in \bigoplus_{s=1}^r M_{n_s}(\mathbb C) \otimes 1_{C_s}$, which therefore commutes with all $\tilde{e}_{ij}^{(s)}$, we obtain
\begin{equation} 
\begin{aligned}
    \tilde{e}_{ii}^{(s)} \left( c_0 w \right) \tilde{e}_{jj}^{(k)} & = c_0 \cdot \tilde{e}_{ii}^{(s)} \cdot \left( \bigoplus_{l=1}^r \tilde{e}_{34}^{(l)} \right) \cdot \tilde{e}_{jj}^{(k)} \notag \\
    & = \delta_{3i} c_0 \cdot \tilde{e}_{34}^{(s)} \cdot \tilde{e}_{jj}^{(k)} \notag \\
    & = \delta_{3i} \delta_{4j} \delta_{ks} \cdot c_0 \cdot \tilde{e}_{34}^{(s)} 
\end{aligned}
\end{equation}
and
\begin{equation}
    \tilde{e}_{ii}^{(s)} \left( w^*c_0^* \right) \tilde{e}_{jj}^{(k)} = \delta_{4i} \delta_{3j} \delta_{ks} \cdot c_0^* \cdot \tilde{e}_{43}^{(s)}.
\end{equation}
Combining these computations and using that $e$ is orthogonal to $\tilde{e}_{ii}^{(s)}$, we find for all $1 \leq j \leq 4$ that
\begin{equation} 
\begin{aligned}
    0 & = \tilde{e}_{55}^{(s)} \left( ebe \right) \tilde{e}_{jj}^{(s)} \\ 
    & = \tilde{e}_{55}^{(s)} \left( b_0 f \right) \tilde{e}_{jj}^{(s)}  \\
    & = \tilde{e}_{55}^{(s)} \left( v + v^*\right) \tilde{e}_{jj}^{(s)}   \\
    & = \tilde{e}_{55}^{(s)} \left( du + u^* d^*\right) \tilde{e}_{jj}^{(s)}  \\
    & = \tilde{e}_{55}^{(s)} \left( c_0 w + w^* c_0^* \right) \tilde{e}_{jj}^{(s)}.
\end{aligned}
\end{equation}
Hence, for all $1 \leq j \leq 4$ and $1 \leq s \leq r$,
\begin{equation}
    \lambda_1 \tilde{e}_{5j}^{(s)} = \tilde{e}_{55}^{(s)} \cdot y \cdot \tilde{e}_{jj}^{(s)} \in B.
\end{equation}
This proves the claim. 
\end{proof}

\begin{claim}
	The elements $u, v$ and all the matrix units $\tilde{e}_{ij}^{(s)}$ belong to $B$.
\end{claim}
\begin{proof}[Proof of the claim]
The matrix units belong to $B$ by the following calculation:
\begin{equation}
    \tilde{e}_{ij}^{(s)} = \tilde{e}_{i5}^{(s)} \tilde{e}_{5j}^{(s)} \in B.
\end{equation}
Since $u$ and $v$ are spanned by elements of this form, we obtain that $u$ and $w$ are also elements in $B$.

We proceed to show that $v$ also belongs to $B$. To this end, we calculate $q_1 y e$.
By construction, $d, q, q_1, u, w, z \in fAf$. Since $e$ and $f$ are orthogonal we obtain
\begin{equation}
    q_1 ebe = q_1 b_0 f e = q_1 z e = q_1 (du + u^* d^*) e = 0.
\end{equation}
On the other hand, since $c_0$ commutes with $q_1$ and $w$, the previous argument yields
\begin{equation}
	q_1 (c_0 w + w^* c_0^*) e = c_0^* q_1 w^* e = 0.
\end{equation}
Combining these calculations with $v \in q_1Ae$ yields
\begin{equation}
    q_1 y e = \lambda_2 q_1 \left( v + v^* \right) e = \lambda_2 q_1  v e = \lambda_2 v.
\end{equation}
This shows that
\begin{equation}
    v = \lambda_2^{-1} q_1 y e \in B. 
\end{equation}
\end{proof}

\begin{claim}
	The elements $d, ece$ and $c_0f$ belong to $B$.
\end{claim}
\begin{proof}[Proof of claim]
Proceeding as before, we compute $q_1 y q_2$ to deduce that $d$ lies in $B$.
Applying the calculations from the proof of Claim \ref{claim:e5i}, we obtain
\begin{equation} 
	0 = q_1 ebe q_2 = q_1 b_0 f q_2 = q_1 z q_2 = q_1 (v + v^*) q_2 = q_1 \left( c_0 w + w^* c_0^* \right) q_2.
\end{equation}
As $d\in q_1Aq_1$ and $u\in q_1Aq_2$, we have
\begin{equation}
    q_1 y q_2
    = \lambda_3 q_1 \left( du + u^* d^* \right) q_2 = \lambda_3 q_1 d u q_2 = \lambda_3 d u. 
\end{equation}
Using that $uu^* = q_1$, $q \leq q_1$ and $d \in qAq$, we obtain
\begin{equation}
    d = \lambda_3^{-1} q_1 y q_2 u^* \in B. 
\end{equation}
In particular, this implies 
\begin{equation}
    ece = v^* d v \in B.
\end{equation}
Using similarly that
\begin{equation}
    q_3 e = q_3 b_0 f q_4 = q_3 z q_4 = q_3  \left( du + u^* d^* \right) q_4 = 0,
\end{equation}
we obtain
\begin{equation}
     q_3 y q_4 = \lambda_4 q_3 \left( c_0 w + w^* c_0^* \right) q_4 = \lambda_4 c_0 w.
\end{equation}
This yields
\begin{equation}
    c_0 q_3 = c_0 ww^* = \lambda_4^{-1} q_3 y q_4 w^* \in B.
\end{equation}
By conjugating $c_0q_3$ by $\bigoplus_{s=1}^r 1_{M_s}\otimes e^{(s)}_{3i} \in B$ for all $1\leq i \leq 5$ and noting that these elements commute with $c_0 \in \bigoplus_{s=1}^r M_{n_s} \otimes 1_{C_s}$, it follows that
\begin{equation}
    c_0q_i = \left(\bigoplus_{s=1}^r 1_{M_s}\otimes e^{(s)}_{i3}\right) c_0 q_3 \left(\bigoplus_{s=1}^r 1_{M_s}\otimes e^{(s)}_{3i}\right) \in B.
\end{equation}
This in turn implies
\begin{equation}
    c_0 f = \sum_{i=1}^5 c_0 q_i \in B.
\end{equation}
This completes the proof of the claim.
\end{proof}

We will finish the proof of the theorem in the unital case by showing that $c$ is close to $B$. Indeed, by \eqref{eq:fF_approxcommute}, we have
\begin{align}
    c = fcf + ecf + fce + ece \approx_{8\delta} fcf + ece \approx_{\delta} c_0 f + ece \in B.
\end{align}
Therefore, we have shown that $x \approx_\varepsilon a$ and $y \approx_\varepsilon b$ and $c \in_\varepsilon B$. This proves that the generator rank of $A$ is at most 1.

If $A$ is not unital, we use that $A$ has an approximate unit $(e_n)$ consisting of projections. Then, we set $A_n:= e_n A e_n$, which is a unital, simple \ensuremath{C^*}-algebra. Since $A_n$ is a hereditary subalgebra of $A$, it follows that $A_n$ is also tracially AF with real rank zero and strict comparison (\cite{Lin01}). 
Then, by the above argument, we obtain that $\mathrm{gr}(A_n) \leq 1$ for all $n \in \mathbb{N}$. By Theorem \ref{thm:gr.ind.limits}, we finally obtain $\mathrm{gr}(A) \leq 1$.

Let us verify first that $x$ is close to $a$. Indeed,
\begin{equation} 
\begin{aligned}
	x-a & = x - eae - fae - eaf - faf \\
	& \approx_{8\delta} x-eae-faf \\
	& = x - eae - fpapf \\
	& \approx_{\delta} a_1 + \sum_{s=1}^r \sum_{k=1}^5 \left( a_0^{(s)} + \frac{k \mu}{5} \right) \otimes e_{kk}^{(s)} -eae - fa_0f \\
