Let $a_1, ..., a_n$ and $b_1, ..., b_m$ be positive elements in a \ensuremath{C^*}-algebra $A$, with $n\geq m$ and the $b_i$ mutually orthogonal. We say the tuple $(a_i)_i$ is \emph{subordinate} to $(b_j)_j$ if the assignment
    \begin{equation}
        \{1, ..., n\} \to \{1, ..., m\}: i \mapsto j\quad \text{ with } j \text{ such that } a_i \leq b_j
    \end{equation}
    is a well-defined, surjective, order-preserving map. In other words, each $a_i$ is under precisely one $b_j$, each $b_j$ has at least one $a_i$ under it, and the $a_i$ are grouped by the $b_j$ they are under, in the same order as the $b_j$.

\label{def:area}
    Let $D$ be a unital \ensuremath{C^*}-algebra with a faithful trace $\tau$ and $p_{1},\dots,p_{n} \in D$ a partition of unity for $D$.
    The \emph{area} of an element $x \in D$ with respect to $\{p_{i}\}_{i=1}^{n}$ and $\tau$ is
    \begin{equation}
        \mathcal{I}(x\mid \{p_{i}\}_{i=1}^{n})=\sum_{i,j:p_{i}xp_{j}\neq0}\tau(p_{i})\tau(p_{j}).
    \end{equation}
    The \emph{support} of $x$ with respect to $\{p_{i}\}_{i=1}^{n}$ and $\tau$ is
    \begin{equation}
        \mathcal{S}(x\mid \left\{p_i\right\}_{i=1}^n)=\sum_{ p_ix\neq0 \text{ or } xp_i\neq0} p_i.
    \end{equation}

\label{def:smallarea}
    Let $A$ be a unital $C^*$-algebra, and $D$ a unital $C^*$-subalgebra of $A$ with faithful trace $\tau$. We say an element $x\in A$ has \emph{small area} with respect to $(D,\tau)$ if for every $\varepsilon>0$, there exists a partition of unity $\left\{p_i\right\}_{i=1}^n$ for $D$ (i.e.\ each $p_i$ is in $D$) such that
    \begin{equation}
        \mathcal{I}(x\mid \left\{p_i\right\}_{i=1}^n) < \varepsilon.
    \end{equation}

\label{lemma:areaprops}
    Let $A$ be a unital $C^*$-algebra, $D$ a unital $C^*$-subalgebra with a faithful trace $\tau$, $\{p_i\}_{i=1}^n$ a set of pairwise orthogonal projections in $D$ summing up to $p \in D$, and $x \in A$.
    \begin{enumerate}
        \item \label{lemma:areaprops_commute} If $x$ commutes with $\{p_i\}_{i=1}^n$, then
        \begin{equation}
        \mathcal{I}(x\mid \{p_i\})\leq n \max_{1\leq i\leq n}\tau(p_i)^2.
        \end{equation}

        \item \label{lemma:areaprops_refine} For any refinement $\{p_{i,j}\}_{1\leq i\leq n, 1\leq j\leq n_{i}}$ of $\{p_i\}_{i=1}^n$, we have
        \begin{equation}
        \mathcal{I}(pxp\mid \{p_{i,j}\}_{1\leq i\leq n, 1\leq j\leq n_{i}})\leq \mathcal{I}(pxp\mid \{p_{i}\}_{i=1}^{n}).
        \end{equation}
        \item \label{lemma:areaprops_onesided} For any $y,z \in pA$, we have
        \begin{equation}
        \mathcal{I}(yz^*\mid \{p_i\})\leq \tau(\mathcal{S}(yy^*\mid \{p_i\})) \tau(\mathcal{S}(zz^*\mid \{p_i\})).
        \end{equation}
    \end{enumerate}

(\ref{lemma:areaprops_commute}):
    As
    \begin{equation}
        0 \neq p_i x p_j = x p_i p_j = \delta_{ij} x p_i
    \end{equation}
    implies $i=j$ for all $i,j$, it follows that
    \begin{equation}
         \mathcal{I}(x\mid \{p_i\})\leq \sum_{i=j} \tau(p_i)\tau(p_j) \leq n \max_{1\leq i\leq n}\tau(p_i)^2.
    \end{equation}   

(\ref{lemma:areaprops_refine}):
    This follows immediately from the fact that
    \begin{equation}
         \sum_{k,l: p_{i,k}xp_{j,l}\neq 0} \tau(p_{i,k})\tau(p_{j,l}) \leq \sum_{k,l} \tau(p_{i,k})\tau(p_{j,l}) = \tau(p_i)\tau(p_j)
    \end{equation}
    for all $i$ and $j$.

(\ref{lemma:areaprops_onesided}):
    We claim that 
    \begin{equation}
        xx^*p_i\neq 0\iff p_i xx^*\neq 0\iff p_ix\neq 0.
    \end{equation}
    The first equivalence is immediate, and so is the forward direction of the second.
    Suppose that $p_ixx^*=0$.
    Then $(p_ix)(p_ix)^*=p_ixx^*p_i=0$ and so $p_i x=0$.
    The same of course holds for $y$ in place of $x$.
    Hence
    \begin{equation}
        \begin{aligned}
            \mathcal{I}(xy^*\mid \{p_i\})&=\sum_{i,j:p_ixy^*p_j\neq0}\tau(p_i)\tau(p_j)\\
            &\leq \sum_{\substack{i:p_ix\neq0\\j:y^*p_j\neq 0}}\tau(p_i)\tau(p_j)\\
            &=\sum_{i:p_ixx^*\neq0\text{ or }xx^*p_i\neq 0}\tau(p_i)\sum_{j:p_jyy^*\neq0\text{ or }yy^*p_j\neq 0}\tau(p_j)\\
            &=\tau(\mathcal{S}(xx^*\mid\{p_i\}))\tau(\mathcal{S}(yy^*\mid \{p_i\})),
        \end{aligned}
    \end{equation}
    finishing the proof.

\label{thm:shen}
    Let $A$ be a \ensuremath{C^*}-algebra and $B\subseteq A$ a unital \ensuremath{C^{*}}-subalgebra with a faithful trace $\tau$.
    Suppose that $\left\{e_{ij}\right\}_{1\leq i,j\leq n}$ are matrix units of a unital copy of $M_n$ inside $A$ with $n\geq 4$ such that $e_{ii}\in B$ for all $i$.
    If $x_1,\dots,x_k$ are elements of $A$ such that
    \begin{equation}
        \sum_{i=1}^k\mathcal{I}(x_i\mid \left\{e_{jj}\right\}_{j=1}^n)=c^2
    \end{equation}
    with $c\leq 1/4$, then there is a projection $q\in \ensuremath{C^*}(x_1,\dots,x_k,\left\{e_{ij}\right\})$ such that
    \begin{equation}
        \tau(\mathcal{S}(q\mid \left\{e_{ii}\right\})\leq 2c + 2/n
    \end{equation}
    and 
    \begin{equation}
        \ensuremath{C^*}(q,\left\{e_{ij}\right\})=\ensuremath{C^*}(x_1,\dots,x_k,\left\{e_{ij}\right\}).
    \end{equation}

\label{lemma:single-generation-with-projections}
    Let $A$ be a \ensuremath{C^*}-algebra generated by countably many commuting projections.
    Then $A$ is generated by a single self-adjoint element.

Since projections in $C(X)$ correspond 1-1 to clopen subsets and projections in $L^{\infty}(X)$ correspond 1-1 to measurable sets modulo null sets, the statement is equivalent to the following: For every $Y\subseteq X$ measurable there is $\tilde{Y}\subseteq X$ clopen such that 
    \begin{equation}
         \mu_{\tau}(Y\Delta\tilde{Y})\leq\varepsilon.
    \end{equation}

    Here $\Delta$ denotes the symmetric difference of two sets.
    As $\mu_{\tau}$ is regular, $Y$ is measurable and $X$ is compact, there is compact $K\subseteq Y$ and an open set $U$ such that $Y \subseteq U$ and $\mu_{\tau}(U\setminus K)\leq \varepsilon$. Since $U$ is open and $X$ is 0-dimensional, $U$ is a (possibly infinite) union of clopens so by compactness of $K$, there are finitely many clopens $\left\{U_{i}\right\}_{i=1}^{n}$ such that 
    \begin{equation}
       K\subseteq\bigcup_{i=1}^{n}U_{i}\subseteq U. 
    \end{equation}
    Let $\tilde{Y}=\bigcup_{i=1}^{n}U_{i}$ and observe that $Y\Delta\tilde{Y}\subseteq U\setminus K$ so $\mu_{\tau}(Y\Delta\tilde{Y})\leq\varepsilon$.

Set $\delta=\frac{\varepsilon}{2n+1}$.
    Lemma~\ref{lemma:approximating-projections} provides projections $q_{1},\dots,q_{n}\in C(X)$ such that $\lVert q_{i}-p_{i}\rVert_{\tau}\leq \delta$. 
    Now let 
    \begin{align}
        \tilde{p}_{1}&=q_{1},\text{ and}\\
        \tilde{p}_{i}&=q_{i}(1-\sum_{k=1}^{i-1}\tilde{p}_{k}).
    \end{align}
    Note that these are pairwise orthogonal by construction.
    Since \begin{align}\left\lVertq_iq_k\right\rVert_\tau\leq 2\delta+\left\lVertp_ip_k\right\rVert_\tau=2\delta,
    \end{align} 
    we estimate
    \begin{equation}
    \begin{aligned}
        \lVert p_{i}-\tilde{p}_{i}\rVert_{\tau}&\leq\lVert p_{i}-q_{i}\rVert_{\tau}+\lVert q_{i}-\tilde{p}_{i}\rVert_{\tau}\\
        &\leq \delta+\lVert q_i \sum_{k=1}^{i-1}\tilde{p}_{k}\rVert_{\tau}\\
        &\leq\delta+ \sum_{k=1}^{i-1}\lVert q_{i}q_k\tilde{p}_{k}\rVert_{\tau}\\
        &\leq (2n+1)\delta=\varepsilon
    \end{aligned}
    \end{equation}
    as desired.

Pick $a\in A\cap C(X)'$ and $0<\varepsilon<1$. As $\tau$ is diffuse, there exists a partition of unity $\{p_i\}_{i=1}^n$ for $L^\infty(X,\mu_\tau)$ such that $\tau(p_i) = 1/n$ for all $i$ and $n\in\mathbb N$ such that
\begin{equation}
    \frac{4}{n^2} \leq \frac{\varepsilon}{n+1}\leq 1.
\end{equation}
Use Lemma \ref{lemma:approximating-multiple-projections} to find mutually orthogonal projections $\tilde p_1, ..., \tilde p_n$ with
\begin{equation}
    \|p_i-\tilde p_i\|_\tau \leq \varepsilon_0 := \frac{1}{n}\sqrt{\frac{\varepsilon}{n+1}} \leq \frac{1}{n}.
\end{equation}
Writing $\tilde p_{n+1} := 1- \sum_{i=1}^n \tilde p_i \in C(X)$, it follows from Kadison's inequality that
\begin{equation}
    \tau(\tilde p_{n+1}) \leq 1-\sum_{i=1}^n(1/n-\varepsilon_0) = n\varepsilon_0.
\end{equation}
Hence, $\{\tilde p_i\}_{i=1}^{n+1}$ is a partition of unity for $C(X)$ satisfying (using the same estimate as above for $\tau(\tilde p_i)$)
\begin{equation}
\begin{aligned}
    \max_{1\leq i \leq n+1} \tau(\tilde p_i)^2
        &\leq \max \left\{ (1/n+\varepsilon_0)^2, n^2\varepsilon_0^2 \right\} \\
        &\leq \max \left\{ 4/n^2, \varepsilon/(n+1) \right\} = \varepsilon/(n+1).
\end{aligned}
\end{equation}
As $a$ commutes with $C(X)$, we can use Lemma~\ref{lemma:areaprops}.\ref{lemma:areaprops_commute} to conclude that ${\mathcal{I}(a \mid \{\tilde p_i\}_{i=1}^{n+1})} \leq \varepsilon$, as desired.

\label{lemma:equalizing-projections}
    Let $X$ be the Cantor space, $\tau$ a faithful, diffuse trace on $C(X)$ and $\{p_{i}\}_{i=1}^{n}$ a partition of the unit of $C(X)$.
    For any $\varepsilon>0$ and $N\in \mathbb{N}$, there is a refinement $\{p_{i,j}\}_{1\leq i\leq n, 1\leq j\leq n_{i}}$ of $\{p_{i}\}_{i=1}^{n}$ such that $\sum_{i,j}p_{i,j}=1$, $K=\sum_{i=1}^{n}n_{i}\geq N$ and
    \begin{equation}
       1-K\min_{i,j}\tau(p_{i,j})\leq\varepsilon.
    \end{equation}

We prove an analog in $L^{\infty}(X,\mu_\tau)$ and transport it approximately to $C(X)$ using Lemma~\ref{lemma:approximating-multiple-projections}.
    Let $t_{i}:=\tau(p_{i})$ and find $s_{i}=a_{i}/b_{i}$ with $a_i,b_i\in \ensuremath{\mathbb{Z}} $ such that $0\leq t_{i}-s_{i}\leq\frac{\varepsilon}{2n}$.
    Then $\sum_{i=1}^n s_i\geq 1-\varepsilon/2$.
    Let $m:=Nb_{1}\cdots b_{n}\in \mathbb{Z}$. 

    For each $i$ and $1\leq j\leq n_{i}:=ms_{i}$, use diffuseness of $\tau$ to find pairwise orthogonal projections $\tilde{p}_{i,j}\leq p_{i}$ in $L^{\infty}(X,\mu_\tau)$ such that $\tau(\tilde{p}_{i,j})=1/m$. 
    Defining $K:=\sum_{i=1}^{n}n_{i}\geq N\sum_{i=1}^n a_i\geq N$, we then have
    \begin{equation}
    \label{eq:equalizing-projections-estimate}
        K\tau(\tilde{p}_{i,j})=\sum_{i=1}^n n_i/m=\sum_{i=1}^n s_i\geq1-\varepsilon/2.
    \end{equation}
    Using Lemma~\ref{lemma:approximating-multiple-projections}, find pairwise orthogonal projections $q_{i,j}$ in $C(X)$ such that 
    \begin{equation}
        \lVert q_{i,j}-\tilde{p}_{i,j}\rVert_{\tau}\leq \frac{\varepsilon}{2K}.
    \end{equation}
    For each $i,j$, the projection
    \begin{equation}
        p_{i,j}:=q_{i,j}p_{i}
    \end{equation}
    still satisfies $\left\lVertp_{i,j}-\tilde{p}_{i,j}\right\rVert_\tau\leq \frac{\varepsilon}{2K}$ as $\tilde{p}_{i,j}\leq p_i$, so
    \begin{equation}
        \left|\tau(p_{i,j})-\tau(\tilde{p}_{i,j})\right|\leq \left\lVert p_{i,j}-\tilde{p}_{i,j}\right\rVert_{\tau}\leq \frac{\varepsilon}{2K}
    \end{equation}
    by Kadison's inequality. Hence, \eqref{eq:equalizing-projections-estimate} gives
    \begin{equation}
        \begin{aligned}
            1-K\min_{i,j}\tau(p_{i,j})&\leq 1-K\min_{i,j}\tau(\widetilde p_{i,j}) +K\frac{\varepsilon}{2K}\\
            &\leq \frac{\varepsilon}{2}+\frac{\varepsilon}{2}=\varepsilon.
        \end{aligned}
    \end{equation}

    Replacing $p_{i,1}$ by $p_{i}-\sum_{j=2}^{n_{i}}p_{i,j}$, the value of $1-K\min_{i,j}\tau(p_{i,j})$ can only decrease and the $p_{i,j}$ now form a partition of unity, giving the desired refinement.

Let $n_0$, $\varepsilon_0$, $\{e^{(0)}_{ii}\}_{i=1}^{n_0}$, $\{\widetilde e^{(0)}_{i}\}_{i=1}^{n_0}$ be as in the statement.
Fix $\varepsilon_1>0$ and a partition $\left\{q_k\right\}_{k=1}^N$ of the unit of $B$.

Note that the set of projections $\{e^{(0)}_{11}q_{j}\}_{j} \cup \{(1-e^{(0)}_{11})\widetilde e^{(0)}_iq_{j}\}_{i,j}$ is a partition of unity for $C(X)$.
Lemma \ref{lemma:equalizing-projections} provides $n_1\geq 4/\varepsilon_1$ -- giving condition (P5) -- and a partition of unity $\widetilde e^{(1)}_{1},\dots,\widetilde e^{(1)}_{n_1}\in C(X)$ for $C(X)$ refining $\{e_{11}^{(0)}q_{j}\}_{j}\cup\{(1-e_{11}^{(0)})\widetilde e^{(0)}_iq_{j}\}_{i,j}$ such that
\begin{equation} \label{eq:fihavesimilartrace}
    1-n_1\min_{i}\tau(\widetilde e^{(1)}_{i})\leq \frac{\varepsilon_1}{4}.
\end{equation}
By reindexing if necessary, we may assume that $(\widetilde e^{(1)}_i)_i$ is subordinate to $(\widetilde e^{(0)}_{i})_i$ and $\widetilde e^{(1)}_{1} \leq e^{(0)}_{11}$.
Using 0-dimensionality of $X$, find a projection $e^{(1)}_{11}\in C(X)$ such that 
\begin{equation} \label{eq:f11traceclosetofi}
    \min_{i}\tau(\widetilde e^{(1)}_{i})-\frac{\varepsilon_1}{4n_1}\leq \tau(e^{(1)}_{11})<\min_{i}\tau(\widetilde e^{(1)}_{i})
\end{equation}
and $e^{(1)}_{11}\leq \widetilde e^{(1)}_{1}$; this ensures (P1).
Applying strict comparison or dynamical comparison gives for each $1\leq i\leq n_1$ partial isometries $f_{i}\in B$ for such that $f_{i}^{*}f_{i}=e^{(1)}_{11}\in C(X)$ and $f_{i}f_{i}^{*}\leq \widetilde e^{(1)}_{i}$.
In the case of dynamical comparison, we furthermore have $f_{i}f_{i}^{*}\in C(X)$ for all $i$.
For each $i$ and $j$, write $e^{(1)}_{ij} := f_{i}f_{j}^{*}$. 
Then $\operatorname{Span}(e^{(1)}_{ij})$ is a copy of $M_{n_1}$ with unit $p_1=\sum e^{(1)}_{ii}$ such that each $e^{(1)}_{ii}$ is under $\widetilde e^{(1)}_i$, so (P3) holds. As the $\widetilde e^{(1)}_i$ are a refinement of $\{e^{(0)}_{11}, 1-e^{(0)}_{11}\}$, we have also arranged (P2).

To prove that condition (P8) for $a=v_1$ is satisfied, observe the following. Since $e^{(1)}_{ii}\leq \widetilde e^{(1)}_i$ and $(\widetilde e^{(1)}_i)_i$ is subordinate to $(\widetilde e^{(0)}_i)_i$, for each $1\leq k\leq n_1$ there is a unique $1\leq i_k\leq n_{0}$ such that $e^{(1)}_{kk}\leq \widetilde e^{(0)}_{i_k}$, and $i_{k+1} \in \{i_k, i_k+1\}$. Consequently, if for arbitrary $i$, $j$ and $k$ we have
\begin{equation}
    0 \neq e^{(0)}_{ii} e^{(1)}_{k,k+1} e^{(0)}_{jj} = e^{(0)}_{ii} \widetilde e^{(0)}_{i_k} e^{(1)}_{k,k+1} \widetilde e^{(0)}_{i_{k+1}} e^{(0)}_{jj},
\end{equation}
then also $0\neq e^{(0)}_{ii} \widetilde e^{(0)}_{i_k} \leq \widetilde e^{(0)}_{i} \widetilde e^{(0)}_{i_k}$ and $0 \neq \widetilde e^{(0)}_{i_{k+1}}e^{(0)}_{jj} \leq \widetilde e^{(0)}_{i_{k+1}}\widetilde e^{(0)}_{j}$. 
This is only possible for $i=i_k$ and $j=i_{k+1}\in \{i_k, i_k+1\}$, so $j=i$ or $j=i+1$. 
Therefore, the element $v_{1}=\sum_{i=1}^{n_{1}-1}e_{i,i+1}^{(1)}+e_{i+1,i}^{(1)}$ satisfies 
\begin{equation}
        \mathcal{I}(p_{0}v_{1}p_{0}\mid \{e_{ii}^{(0)}\})\leq 4n_{0}\tau(e_{11}^{(0)})^{2}.
\end{equation}
Since $\{e_{ii}^{(0)}\}_{i=1}^{n_0}$ are pairwise orthogonal and of equal trace, we have $\tau(e^{(0)}_{ii}) = \tau(e_{11}^{(0)})\leq 1/n_{0}$ for all $i$, so we can further bound the above expression as
\begin{equation}
        \mathcal{I}(p_{0}v_{1}p_{0}\mid \{e_{ii}^{(0)}\})\leq \frac{4}{n_{0}}\leq \varepsilon_{0},
\end{equation}
proving that (P8) holds.

To show (P6), we compute
\begin{equation}
\label{eq:trace-estimate-1}
\begin{aligned}
    \tau(1-p_1)&=1-\sum_{i=1}^{n_1}\tau(e^{(1)}_{ii})\\
    &=1 -n_1\tau(\widetilde e^{(1)}_{1}) + n_1(\tau(\widetilde e^{(1)}_{1})-\tau(e^{(1)}_{11}))\\
    &\leq \frac{\varepsilon_1}{4}+ n_1\frac{\varepsilon_1}{4n_1}=\frac{\varepsilon_1}{2}\,
\end{aligned}
\end{equation}
using \eqref{eq:fihavesimilartrace} and \eqref{eq:f11traceclosetofi}.

We will now construct the partial isometry $w_1$ such that conditions (P4), (P7), and (P8) for $a=w_1$ hold. 
By combining \eqref{eq:fihavesimilartrace} and \eqref{eq:f11traceclosetofi}, we find
\begin{equation}
    \frac{\varepsilon_1}{2n_1} < \frac{1}{n_1}\left(1-\frac{\varepsilon_1}{2}\right) \leq \tau(e^{(1)}_{11}) \leq \frac{1}{n_1}\leq \frac{\varepsilon_1}{2},
\end{equation}
so there exists an integer $m\leq n_1$ such that $\varepsilon_1/2 <m\tau(e^{(1)}_{11})\leq\varepsilon_1$. Denoting by $M$ the number of $e^{(1)}_{ii}$ which are under $e^{(0)}_{11}$, we now claim that $M\geq m$. To see this, recall that we have already shown condition (P2), so as $\{e^{(1)}_{ii}\}_i\cup\{1-p_1\}$ partitions $B$, we can observe that
\begin{equation}
    M\tau(e^{(1)}_{11}) + \tau(1-p_1) \geq \tau(e^{(0)}_{11}) \geq 2\varepsilon_1.
\end{equation}
Hence, we find
\begin{equation}
    M\tau(e^{(1)}_{11}) \geq \frac{3}{2}\varepsilon_1 \geq m \tau(e^{(1)}_{11})
\end{equation}
which proves our claim. 

Recalling that $(\widetilde e^{(1)}_i)_i$ is subordinate to $(\widetilde e^{(0)}_i)_i$, it follows that $e^{(1)}_{ii}\leq e^{(0)}_{11}$ for all $1\leq i\leq M$, so 
\begin{equation}
\label{eq:trace-estimate-2}
    \tau\left(\sum_{i=1}^M e^{(1)}_{ii} \right) =M\tau(e^{(1)}_{11}) \geq m\tau(e^{(1)}_{11}) >\frac{\varepsilon_1}{2}.
\end{equation}
When working with strict comparison, combining \eqref{eq:trace-estimate-1} and \eqref{eq:trace-estimate-2} immediately gives a $w_1\in B$ satisfying (P4).
In the setting of dynamical comparison, note that $1-p_1$ and $\sum_{j=1}^M e_{ii}^{(1)}$ are both in $C(X)$, so we can use the same trace estimates to obtain a $w_1 \in B$ satisfying (P4).

Moreover, we have
\begin{equation}
\begin{aligned}
    \tau(\mathcal{S}(w_1w_1^*\mid \{e^{(1)}_{ii}\}))
        &\leq \tau\left(\mathcal{S}\left(\sum_{i=1}^m e^{(1)}_{ii}\mid \{e^{(1)}_{ii}\}\right)\right) \\
        &= m \tau(e^{(1)}_{11}) \leq \varepsilon_1,
\end{aligned}
\end{equation}
so condition (P7) holds. Finally, we also find that 
\begin{equation}
    e^{(0)}_{jj}p_{0}w_1p_{0}=e^{(0)}_{jj}w_1p_{0}\neq0 \implies j=1
\end{equation}
for all $j$, so 
\begin{equation}
    \mathcal{I}(p_{0}w_1p_{0}\mid \{e^{(0)}_{ii}\})\leq \frac{1}{n_{0}} \leq \varepsilon_{0},
\end{equation}
which settles (P8) for $a=w_1$, finishing the proof.

Without loss of generality, assume $x_1 = 0$. We first prove the following claim:
\begin{claim} \label{claim:inductive}
    For each $l\in \mathbb{N}$, there exist a matrix algebra $M_{n_l} = \operatorname{Span}\{e^{(l)}_{ij}\}_{i,j=1}^{n_l}$ in $B$ with unit $p_l = \sum_{i=1}^{n_l} e^{(l)}_{ii}$, a partition of unity $\{\widetilde e^{(l)}_{i}\}_{i=1}^{n_{l}}$ and a partial isometry $w_l \in B$ such that all conditions in Lemma \ref{lemma:inductive-step-v5} hold (replacing the index $0$ by $l-1$ and $1$ by $l$), as well as
    \begin{enumerate}
        \item[(P9)] $\mathcal{I}(p_{l}x_lp_{l}\mid \{e_{ii}^{(l)}\})\leq \varepsilon_{l}$.
    \end{enumerate}
    If $C(X)$ has dynamical comparison relative to $B$, then moreover all $e^{(l)}_{ii}$ ($l\in \mathbb{N}$, $1\leq i \leq n_l$) are in $C(X)$.
\end{claim}
\begin{proof}[Proof of claim]
We run an inductive argument. For the base case ($l=1$), it suffices to define the input data for Lemma \ref{lemma:inductive-step-v5} to start the inductive process. Letting $n_0 = 1$, $e^{(0)}_{11} = \widetilde e_1^{(0)}=1 \in C(X)$ and $\varepsilon_0 = 4$ does the trick, recalling that $x_1=0$.

Now for the inductive step, suppose we are given the data as in the claim for $l-1$. Fix $\varepsilon_l\leq \tau(e^{(l-1)}_{11})/2000$. By assumption, there exists a partition $\{q_k\}_{k=1}^N$ of the unit of $C(X)$ such that
\begin{equation}
\label{eq:xlsmallarea}
    \mathcal{I}(x_l \mid \{q_k\}_k) \leq \varepsilon_l.
\end{equation}
Applying Lemma~\ref{lemma:inductive-step-v5} in $B$ for $\varepsilon_l$ and $\{q_k\}_k$, there exists a matrix algebra $M_{n_l} = \operatorname{Span}\{e^{(l)}_{ij}\}_{i,j=1}^{n_l}$ in $A$ with unit $p_l = \sum_{i=1}^{n_l} e^{(l)}_{ii}$, and a partial isometry $w_l \in A$ satisfying conditions (P1)-(P8). Moreover, note that $\{e_{ii}^{(l)}\}_i \cup\{(1-p_l)q_k\}_k$ is a refinement of $\{q_k\}_k$, by (P3) and the fact that $\{\widetilde e_{i}^{(l)}\}_i$ refines $\{q_k\}_k$. Combining \eqref{eq:xlsmallarea} and Lemma \ref{lemma:areaprops}.\ref{lemma:areaprops_refine}, it then follows that (P9) also holds. As such, all conditions are satisfied, finishing the inductive step. This proves the claim.
\end{proof}

Fix $l\in \mathbb N$, and consider the corner $p_{l}Ap_{l}$ of $A$, in which the copy of $M_{n_{l}}$ is now unital. We wish to apply Theorem~\ref{thm:shen} to the elements $p_{l}ap_{l}$, $w_{l}ap_{l}$, $p_{l}aw_{l}^{*}$, and $w_{l}aw_{l}^{*}$ for $a\in\{x_{l}, v_{l+1}, w_{l+1}\}$. For all $a\in \{x_l,v_{l+1},w_{l+1}\}$, it follows from (P8) and (P9) that 
\begin{equation}
    \mathcal{I}(p_{l}ap_{l})\mid \{e_{ii}^{(l)}\})\leq \varepsilon_l,
\end{equation}
and using (P7) and Lemma~\ref{lemma:areaprops}.\ref{lemma:areaprops_onesided}, we see that 
\begin{equation}
\begin{aligned}
    \mathcal{I}(w_{l}ap_{l}\mid \{e_{ii}^{(l)}\})&\leq \varepsilon_{l},\\
    \mathcal{I}(p_{l}aw_{l}^{*}\mid \{e_{ii}^{(l)}\})&\leq \varepsilon_{l},\\
    \mathcal{I}(w_{l}aw_{l}^{*}\mid \{e_{ii}^{(l)}\})&\leq \varepsilon_{l}\, .
\end{aligned}
\end{equation}
Theorem~\ref{thm:shen} then applies with 
\begin{equation}
    c\leq \sqrt{12\varepsilon_l}\leq \frac{\tau(e_{11}^{(l-1)})}{12}
\end{equation}
and produces a projection $r_{l}\in p_{l}Ap_{l}$ such that 
\begin{equation}\label{eq:shenprojection}
    C^{*}(r_{l},M_{n_{l}})=C^{*}(p_{l}ap_{l},w_{l}ap_{l},p_{l}aw_{l}^{*},w_{l}aw_{l}^{*},M_{n_{l}}\mid a\in\{x_l, v_{l+1}, w_{l+1}\})
\end{equation}
and 
\begin{equation} \label{eq:support-of-r_lv4}
    \tau(\mathcal{S}(r_{l}\mid \{e_{ii}^{(l)}\}))\leq 2c+2/n_l \leq\frac{\tau(e_{11}^{(l-1)})}{3},
\end{equation}
since $2/n_l\leq \varepsilon_l/2\leq \frac{\tau(e_{11}^{(l-1)})}{4000}$ by (P5).
Let $N=\tau(\mathcal{S}(r_{l}\mid \{e_{ii}^{(l)}\}))/\tau(e_{11}^{(l)})$ be the number of projections $\{e_{ii}^{(l)}\}$ that partition $\mathcal{S}(r_{l}\mid \{e_{ii}^{(l)}\})$.
We claim that there are at least $N$ projections $e_{ii}^{(l)}$ such that $e_{ii}^{(l)}\leq e_{11}^{(l-1)}-e_{11}^{(l)}$. To see this, recall from (P2) that for each $1\leq i\leq n_l$ we either have $e_{ii}^{(l)}\perp e_{11}^{(l-1)}$ or $e_{ii}^{(l)}\leq e_{11}^{(l-1)}$.
Since the projections $\{e_{ii}^{(l)}\}_{i=1}^{n_l}\cup\{1-p_l\}$ partition the unit of $A$, it suffices to show that
\begin{equation}
    \tau(e_{11}^{(l-1)}-e_{11}^{(l)})-\tau(1-p_l)\geq N\tau(e_{11}^{(l)}).
\end{equation}
But this is immediate from (\ref{eq:support-of-r_lv4}), (P1) and (P5). 
By permuting the matrix units $e^{(l)}_{ij}$ appropriately, we may therefore assume that $\mathcal{S}(r_{l}\mid \{e_{ii}^{(l)}\})\leq e_{11}^{(l-1)}-e_{11}^{(l)}$. As $r_l \in p_l A p_l$, we have 
\begin{equation}
    r_l\leq \mathcal{S}(r_l\mid \{e_{ii}^{(l)}\})\leq e_{11}^{(l-1)}-e_{11}^{(l)},
\end{equation}
so $r_l$ commutes with $e_{11}^{(j)}$ for all $j\in\mathbb{N}$.
Note also that $r_l$ and $e_{11}^{(l)}$ commute with $w_1^*w_1=1-p_1$.
Indeed, by construction, $r_l\leq e_{11}^{(l-1)}\leq \dots \leq e_{11}^{(1)}\leq p_1$ for $l\geq 2$ and also $r_1\leq p_1$ by definition.

Hence, we obtain a sequence of projections $r_l \in p_lAp_l$ for all $l\in\mathbb N$, such that the set
\begin{equation}
    S = \{ e^{(l)}_{11}, r_l\}_{l\in\mathbb N} \cup \{w_1^*w_1\}
\end{equation}
consists of pairwise commuting projections. Let 
\begin{equation}
    y=w_{1}+w_{1}^{*}+\sum_{i=1}^{n_{1}-1}e_{i,i+1}^{(1)}+(e_{i,i+1}^{(1)})^* \in A
\end{equation}
and note that $y$ is self-adjoint.

\begin{claim} \label{claim:singlegen}
    $A=\ensuremath{C^*}(y, S)$.
\end{claim}
\begin{proof}[Proof of claim]
    The proof is a slight modification of \cite[Theorem~4.2]{Shen}.
    First notice that since $w_1^*w_1\in  S$,
    \begin{equation}
        w_1^*=w_1^*w_1 y\in \ensuremath{C^*}(y,S)
    \end{equation}
    and so 
    \begin{equation}
        \sum_{i=1}^{n_{1}-1}e_{i,i+1}^{(1)}+(e_{i,i+1}^{(1)})^* = y - w_1 - w_1^* \in \ensuremath{C^*}(y,S)
    \end{equation}
    as well.
    Since $e_{11}^{(1)}\in S$, it follows by a standard argument (see also the proof of \cite[Theorem~3.4]{Shen}) that 
    $M_{n_1}\subseteq \ensuremath{C^*}(y,S)$.
    Hence $\ensuremath{C^*}(r_1,w_1,M_{n_1})\subseteq \ensuremath{C^*}(y,S)$ and so 
    \begin{equation}
        x_1,v_2,w_2\in \ensuremath{C^*}(y,S)
    \end{equation}
    by (P4) and \eqref{eq:shenprojection}.

    Since $e_{11}^{(i)}\in S$, we can proceed inductively, repeatedly using (P4) and \eqref{eq:shenprojection}, to get $x_l\in \ensuremath{C^{*}}(y,S)$.
    Since $A=\ensuremath{C^{*}} (x_l\mid l\in \ensuremath{\mathbb{N}})$, this finishes the proof.
\end{proof}

Finally, Lemma~\ref{lemma:single-generation-with-projections} shows that $\ensuremath{C^*}(S)=\ensuremath{C^*}(z)$ for some self-adjoint $z\in \ensuremath{C^*}(S)\subseteq A$.
Hence, $A$ is generated by two self-adjoint elements $y$ and $z$ and is therefore generated by the element $y+iz$.

