    \end{equation}
    by (P4) and \eqref{eq:shenprojection}.

    Since $e_{11}^{(i)}\in S$, we can proceed inductively, repeatedly using (P4) and \eqref{eq:shenprojection}, to get $x_l\in \ensuremath{C^{*}}(y,S)$.
    Since $A=\ensuremath{C^{*}} (x_l\mid l\in \ensuremath{\mathbb{N}})$, this finishes the proof.

\label{lemma:rokhlin-lemma}
    Let $(X,\mu)$ be a standard Borel probability space and $T\in \operatorname{Aut}(X)$ an invertible measure preserving transformation.
    Let $\varepsilon>0$.
    Then there is $n\in \mathbb{N}$ and measurable sets $E_1,\dots E_n$ such that $E_k,T(E_k),\dots T^{k-1}(E_k)$ are disjoint for $1 \leq k \leq n$.
    Moreover, setting 
    \begin{equation}
        E_\varepsilon=X\setminus \bigcup_{\substack{1\leq i\leq n\\0\leq j\leq i-1}}T^j(E_i)
    \end{equation}
    we have $\mu(E_\varepsilon)<\varepsilon$  and
    $T^k(E_k)\subseteq E_k\cup E_\varepsilon$ for each $1\leq k\leq n$.

For each $k\in \mathbb{N}$, let $X_k$ denote the set of points in $X$ with orbit of size exactly $k$ and $X_\infty$ the set of points with infinite orbit.
    Clearly, $T$ restricts to each $X_k$ for $1\leq k\leq\infty$.
    Pick $n$ large enough so that 
    \begin{equation}
        \mu\left(\bigcup_{n\leq k<\infty}X_k\right)<\varepsilon/2.
    \end{equation}

    For each $1\leq k< n$, find $E_k\subseteq X_k$ such that $X_k$ is the disjoint union of the orbit of $E_k$, see \cite[p.~70,~Lemma~1]{halmos56} for instance.
    Using the Rokhlin lemma, see \cite[p.~71,~Lemma~2]{halmos56} for example, find $E_n \subseteq X_\infty$ such that $E_n, T(E_n), \dots T^{n-1}(E_n)$ are disjoint and 
    \begin{equation}
        \mu\left(\bigcup_{0\leq j\leq n-1}T^j(E_n)\right)>\mu(X_\infty)-\varepsilon/2. 
    \end{equation}

    Notice that since $T$ is invertible, $T^k(E_k)$ is disjoint from
    \begin{equation}
        \bigcup_{1\leq j\leq k-1}T^j(E_k)
    \end{equation} 
    and from $X\setminus X_k$, so we must have 
    $T^k(E_k)\subseteq E_k\cup E_\varepsilon$,
    where 
    \begin{equation}
        E_\varepsilon=X\setminus \bigcup_{\substack{1\leq i\leq n\\0\leq j\leq i-1}}T^j(E_i).
    \end{equation}
    The measure estimate holds by construction.

\label{lemma:lifting-projections-v2}
    Let $A$ be a unital $C^*$-algebra containing a unital copy of $C(X)$ with $X$ the Cantor space. Suppose $A$ has a faithful trace $\tau$ which is diffuse on $C(X)$.
    For any partial isometry $v\in N_A(C(X))$ and $\varepsilon>0$, there are pairwise orthogonal projections\footnote{Note that these may be 0.} 
    \begin{equation}
    \{p^{(i,j)}_k \mid i\in \{1,...,n\}, j\in \{1,...,\ell_i\}, k\in \{0, ..., i-1\}\}
    \end{equation} 
    and $p_{\varepsilon}$ in $C(X)$ such that
    \begin{enumerate}[label=(\roman*)]
        \item $p_\varepsilon + \sum_{i,j,k} p_{k}^{(i,j)}=1$;

        \item $\tau(p_\varepsilon)\leq \varepsilon$;

        \item $\tau(p_k^{(i,j)})^{2}\leq \frac{\varepsilon}{i \ell_i n}$ for all $1\leq i\leq n$ and all $j$ and $k$;

        \item $\operatorname{Ad}_{v} p^{(i,j)}_k \leq p^{(i,j)}_{k+1 \mod i} + p_\varepsilon$ for all $i$, $j$ and $k$.
    \end{enumerate}

Fix $\varepsilon>0$.
    Apply Lemma~\ref{lemma:rokhlin-lemma} with $\varepsilon/2$ to the automorphism $\operatorname{Ad}_u$ of $L^\infty(X,\mu_\tau)$, where $u\in N_{\mathcal{M}}(L^\infty(X,\mu_\tau))$ is a unitary extending $v$ as in Lemma~\ref{lemma:npi_extends}.
    We obtain (by considering indicator functions) $n\in\mathbb{N}$ and pairwise orthogonal projections $\widetilde p_\varepsilon$, $\widetilde p_k^{(i)}\in L^\infty(X,\mu_\tau)$ for some $1\leq i\leq n$ and $0\leq k\leq i-1$.
    These satisfy the following:
    \begin{enumerate}[label=(\arabic*)]
        \item $\widetilde p_\varepsilon+\sum_{i,k} \widetilde p_k^{(i)}=1$,
        \item $\operatorname{Ad}_u \widetilde p_k^{(i)}=\widetilde p^{(i)}_{k+1}$ for all $i$ and $0\leq k\leq i-2$,
        \item $\operatorname{Ad}_u \widetilde p_{i-1}^{(i)}\leq \widetilde p_0^{(i)}+\widetilde p_\varepsilon$,
        \item $\tau(\widetilde p_\varepsilon)\leq \varepsilon/2$.
    \end{enumerate}

    Subdividing each $\widetilde p_0^{(i)}$ into $\widetilde p_0^{(i,j)}$ for $1\leq j\leq \ell_i$ of small enough trace (which is possible by diffuseness of $\tau$) and setting 
    \begin{equation}
        \widetilde p_k^{(i,j)}=\operatorname{Ad}_{u^k}p_0^{(i,j)},
    \end{equation}
    we get pairwise orthogonal projections satisfying

    \begin{enumerate}[label=(\arabic*')]
        \item $\widetilde p_\varepsilon+\sum_{i,j,k} \widetilde p_k^{(i,j)}=1$,
        \item $\operatorname{Ad}_u \widetilde p_k^{(i,j)}=\widetilde p^{(i,j)}_{k+1}$ for all $i$ and $0\leq k\leq i-2$,
        \item $\operatorname{Ad}_u \widetilde p_{i-1}^{(i,j)}\leq \widetilde p_0^{(i,j)}+\widetilde p_\varepsilon$,
        \item $\tau(\widetilde p_\varepsilon)\leq \varepsilon/2$,

        \item $\tau(\widetilde p_k^{(i,j)})^{2}\leq \frac{\varepsilon}{2i \ell_i n}$ for all $i$, $j$ and $k$.
    \end{enumerate}
    Since $v=uv*v$, items (2') and (3') also hold when $u$ is replaced by $v$.
    Fix $\delta>0$, and use Lemma~\ref{lemma:approximating-multiple-projections} to produce pairwise orthogonal projections $\{q^{(i,j)}_k\}_{i,j,k}$ in $C(X)$ such that for all $i$, $j$ and $k$, we have
    \begin{equation}
        \left\lVert q_k^{(i,j)}-\tilde p_k^{(i,j)}\right\rVert_\tau\leq \delta.
    \end{equation}
    Let
    \begin{equation}
    \begin{aligned}
        p_0^{(1,1)}&= q_0^{(1,1)}\\
        p_{0,\delta}^{(1,1)}&=(1-p^{(1,1)}_0)\operatorname{Ad}_v p_0^{(1,1)}        
    \end{aligned}
    \end{equation}
    so that $\operatorname{Ad}_v p_0^{(1,1)}\leq p_0^{(1,1)}+p_{0,\delta}^{(1,1)}$.

    We now wish to construct projections $p_0^{(1,2)}$ and $p_{0,\delta}^{(1,2)}$ such that $\operatorname{Ad}_v p_0^{(1,2)}\leq p_0^{(1,2)}+p_{0,\delta}^{(1,2)}$.
    Moreover we want these two projections to be mutually orthogonal and also orthogonal to $p_0^{(1,1)}$ and $p_{0,\delta}^{(1,1)}$.

    In particular, we need to ensure that $\operatorname{Ad}_v p_0^{(1,2)}$ does not intersect $p_0^{(1,1)}+p_{0,\delta}^{(1,1)}$.
    To do that, we cut by the complement of $\operatorname{Ad}_{v^*}(p_0^{(1,1)}+p_{0,\delta}^{(1,1)})$.
    Explicitly, we set
    \begin{equation}
    \begin{aligned}
        p_0^{(1,2)}&= q_0^{(1,2)}(1-\operatorname{Ad}_{v^*}(p_0^{(1,1)}+p_{0,\delta}^{(1,1)}))\\
        p_{0,\delta}^{(1,2)}&=(1-p_0^{(1,2)})\operatorname{Ad}_v p_0^{(1,2)}.
    \end{aligned}
    \end{equation}

    Proceeding inductively, we construct pairwise orthogonal projections $p_0^{(1,j)}$ and $p_{0,\delta}^{(1,j)}$ for $1\leq j\leq \ell_1$ such that
    \begin{equation}
        \operatorname{Ad}_v p_0^{(1,j)}\leq p_0^{(1,j)}+p_{0,\delta}^{(1,j)}.
    \end{equation}

    More generally, we employ the same strategy to inductively construct pairwise orthogonal projections $p_k^{(i,j)}$ and $p_{k,\delta}^{(i,j)}$ for $1\leq i\leq n$, $1\leq j \leq \ell_i$ and $0\leq k\leq i-1$ such that
    \begin{equation}
    \label{eq:pij-ad}
        \operatorname{Ad}_v p_k^{(i,j)}\leq p_{k+1 \mod i}^{(i,j)}+p_{j,\delta}^{(i,j)}.
    \end{equation}
    To this end, let $p$ be the sum of all projections defined up to this point and fix $i,j$.
    For $0\leq k\leq i-1$ let
    \begin{equation}
    \label{eq:pij-definition}
        p_k^{(i,j)}=q_k^{(i,j)}(1-p)(1-\operatorname{Ad}_{v^*}p)\prod_{k'\neq k +1\mod i}(1-\operatorname{Ad}_{v^*} q_{k'}^{(i,j)}),
    \end{equation}
    and afterwards set
    \begin{equation}
    \label{eq:pij-eps-definition}
                p_{k,\delta}^{(i,j)} = (1-p^{(i,j)}_{k+1 \mod i}) \operatorname{Ad}_v p^{(i,j)}_k.
    \end{equation}
    Note that $p_{k,\delta}^{(i,j)}$ is orthogonal to $p$, as $\operatorname{Ad}_v p_{k}^{(i,j)}$ is.
    Moreover, since $\operatorname{Ad}_v p_k^{(i,j)}$ is orthogonal to $q_{k'}^{(i,j)}$ for $k'\neq k\mod i$, we get that $p_{k,\delta}^{(i)}$ is orthogonal to all $p_{k}^{(i,j)}$.
    Finally, since the $q_k^{(i,j)}$ are pairwise orthogonal, so are the $p_k^{(i,j)}$ and so their images under $\operatorname{Ad}_v$ are as well.
    Hence, the $p_{k,\delta}^{(i,j)}$ are pairwise orthogonal. 
    The inequality \eqref{eq:pij-ad} is satisfied by construction.

    Set
    \begin{equation}
        p_\varepsilon=1-\sum_{i,j,k} p_k^{(i,j)},
    \end{equation}
    and note that by orthogonality, $p_{k,\delta}^{(i,j)}\leq p_\varepsilon$ for all $i$, $j$ and $k$.
    We have thus established conditions (i) and (iv) in the statement so it remains to show that (ii) and (iii) hold provided $\delta$ is chosen small enough.

    We claim that for each $i$, $j$ and $k$, there is a constant $C_{i,j,k}$ depending only on $n$ and the $\ell_i$, such that
    \begin{equation}
        \|p_k^{(i,j)}-\tilde p_k^{(i,j)}\|_\tau\leq C_{i,j,k}\delta.
    \end{equation}
    Indeed, using the fact that $\|q_k^{(i,j)}-\tilde p_k^{(i,j)}\|_\tau\leq \delta$ and that all elements we are working with have norm one, in any expression defining $p_k^{(i,j)}$ or $p_{k,\delta}^{(i,j)}$ one can (inductively) replace all occurrences of $q_k^{(i,j)}$ by $\tilde p_k^{(i,j)}$ at the cost of a finite number $C_{i,j,k}$ of deltas.
    After this replacement, the right hand sides of \eqref{eq:pij-definition} and \eqref{eq:pij-eps-definition} collapse to $\tilde p_k^{(i,j)}$ and 0 respectively. 
    This proves the claim.


    Letting $C=\sum_{i,j,k}^n C_{i,j,k}$, it follows from condition (1') and (4') that $\tau(p_\varepsilon)\leq C\delta+\varepsilon/2$. Choosing
    \begin{equation}
      \delta\leq \min_{1\leq i\leq n}\left\{\frac{\varepsilon}{4Ci\ell_i n},\frac{\varepsilon}{2C}\right\}
    \end{equation}
    guarantees that $\tau(p_\varepsilon)\leq \varepsilon$ and thus condition (ii) holds. 
    Moreover, we compute for all $i$, $j$ and $k$
    \begin{equation}
        |\tau((p_k^{(i,j)}))^2-\tau((\tilde p_k^{(i,j)}))^2|\leq 2|\tau(p_k^{(i,j)})-\tau(\tilde p_k^{(i,j)})|\leq 2||p_k^{(i,j)}-\tilde p_k^{(i,j)}||_\tau\leq \frac{\varepsilon}{2i\ell_i  n}.
    \end{equation}
    Combining the above estimate with condition (5'), verifies condition (iii) and finishes the proof.

\label{prop:cnpi_smallarea}
    Let $A$ be a unital $C^*$-algebra containing a unital copy of $C(X)$ with $X$ the Cantor space. Suppose $A$ admits a faithful trace $\tau$ which is diffuse on $C(X)$.
    Any normalizing partial isometry $v \in N_A(C(X))$ has small area w.r.t.\ $(C(X),\tau)$.

Fix $\varepsilon>0$. 
    Let $\{p^{(i,j)}_k\}_{i,j,k}$ and $p_\varepsilon$ be the projections in $C(X)$ obtained by applying Lemma~\ref{lemma:lifting-projections-v2} to $v$ and $\varepsilon/3$.
    Since $v$ is a normalizer of $C(X)$ we have 
    \begin{equation}
    \begin{aligned}
        qvp_k^{(i,j)}\neq 0\
            & \iff q\operatorname{Ad}_v p^{(i,j)}_k \neq 0 \\
            &\,\implies q=p_{k+1\mod i}^{(i,j)}, \text{ or }p_\varepsilon
    \end{aligned}
    \end{equation}
    for any $q\in \{p^{(i,j)}_k\}_{i,j,k}\cup \{p_\varepsilon\}$.
    This allows us to bound the area of $v$ as follows:
    \begin{equation}
    \begin{aligned}
    \mathcal{I}\left(v\mid \left\{p_k^{(i,j)}\right\}\cup \{p_\varepsilon\}\right)
        &=\tau(p_\varepsilon)\sum_{q:qvp_\varepsilon\neq 0}\tau(q)+\sum_{i,j,k}\tau(p_k^{(i,j)})\sum_{q:qvp_k^{(i,j)}\neq 0} \tau(q)\\
        &\leq\tau(p_\varepsilon)\cdot 1 + \sum_{i,j,k}\tau(p_k^{(i,j)}) \left(\tau(p_\varepsilon) + \tau(p_{k+1\mod i}^{(i,j)}) \right) \\
        &\leq 2\tau(p_\varepsilon) + \sum_{i,j,k} \frac{\varepsilon}{3i\ell_i n} \\
        &\leq 2\varepsilon/3 + \varepsilon/3 =\varepsilon.
    \end{aligned}
    \end{equation}
    This finishes the proof.

By separability of $A$, regularity of $C(X)$ and Lemma \ref{lemma:clopen-normalizers}, there exists a countable set $\{b_n\}_n \subset N_A^c(C(X))$ of clopen normalizers of $C(X)$ generating $A$. Fix $n\in \mathbb N$. By Lemma \ref{lemma:clopen-normalizers}, we can write $b_n = v_n |b_n|$ for some partial isometry $v_n \in N_A^c(C(X))$. As $|b_n| \in C(X)$, it commutes with $C(X)$, so it has small area w.r.t.\ $(C(X),\tau)$ by Corollary~\ref{cor:commuting_smallarea}. The previous proposition implies that $v_n$ also has small area, so we can conclude that the countable set
\begin{equation}
    \left\{v_n\right\}_n \cup \left\{|b_n|\right\}_n
\end{equation}
generates $A$ and consists of elements of small area in $C(X)$.

\label{cor:sg_crossedprod}
    Let $G$ be a countable discrete group with a subgroup $F$, and let $\alpha\colon G\curvearrowright X$ be an action of $G$ on the Cantor space $X$ such that $C(X)\rtimes_\alpha G$ has a faithful trace. Suppose the restricted action $\beta :=\alpha|_F\colon F \curvearrowright X$ induces a monotracial, simple crossed product $C(X)\rtimes_{\beta} F$ such that $C(X)\rtimes _r F$ has strict comparison or $C(X)$ has dynamical comparison relative to $C(X)\rtimes_\beta F$.
    Then $C(X)\rtimes_{\alpha} G$ is singly generated.

\label{rmk:profinite}
    Let $\alpha\colon G\curvearrowright X$ be an action of a discrete countable group $G$ on the Cantor space $X$. The action $\alpha$ is said to be \emph{profinite} if it is induced by actions $\{\alpha_{i}\colon G\curvearrowright X_i\}_{i\in\mathbb{N}}$ on an inverse system of topological spaces
    \begin{equation}
        X\xrightarrow{} \dots\xrightarrow{} X_{3}\xrightarrow{\pi_{2}} X_{2}\xrightarrow{\pi_{1}} X_{1}
    \end{equation}
    with $X$ as its limit, and with surjective connecting maps.

    One can easily obtain free and minimal profinite actions of infinite, residually finite groups as follows.
    Given an infinite, residually finite group $G$, choose a decreasing sequence of normal subgroups 
    \begin{equation}
        G\trianglerighteq N_1 \trianglerighteq N_2\trianglerighteq\dots
    \end{equation}
    with trivial intersection.
    One obtains the inverse system 
    \begin{equation}
        X\rightarrow\dots \rightarrow G/N_2\rightarrow G/N_1
    \end{equation}
    equipped with the natural action of $G$ by coset shifting and with inverse limit homeomorphic to the Cantor space.
    The action of $G$ on $X$ is then free and minimal (see \cite[p.~3 and p.~4]{cortezpetite}).

By assumption, $A$ contains $C(X)$ with $X$ the Cantor space, has a unique trace $\tau$, diffuse on $C(X)$, and is generated by a countable set $\left\{a_n\right\}_n$ of elements of small area w.r.t\ $(C(X),\tau)$. Fixing a countable set $\left\{d_n\right\}_n \subset D$ generating $D$, the elements $1_B\otimes d_n$ ($n\in\mathbb N$) have small area w.r.t.\ $(C(X) \otimes 1_D,\tau)$ by Corollary~\ref{cor:commuting_smallarea}, as they commute with $C(X)\otimes 1_D$. Hence, we can apply Theorem \ref{thm:singlegeneration} for $C(X) \otimes 1_D \subseteq B \otimes 1_D \subseteq A\otimes_\alpha D$ and the countable set
\begin{equation}
    \left\{a_n\otimes 1_D\right\}_n \cup \left\{1\otimes d_n\right\}_n 
\end{equation}
to find that $A$ is singly generated.
